/**
 * Applies the SQL in prisma/migrations to the database, each file once.
 *
 *   bun run db:apply
 *
 * Why not `prisma migrate`: Prisma's CLI connects on port 5432, which is
 * blocked on some networks. This script runs the same migration files through
 * Neon's driver (port 443). The migration SQL itself is generated by Prisma:
 *
 *   bunx prisma migrate diff --from-empty \
 *     --to-schema-datamodel prisma/schema.prisma --script
 *
 * Every statement in those files is inside the "catalogue" schema, so nothing
 * outside it can be changed. Applied files are recorded in
 * catalogue.applied_migrations.
 */
import path from "node:path";
import { readdir } from "node:fs/promises";
import { Pool } from "@neondatabase/serverless";

const migrationsDir = path.resolve(import.meta.dir, "../prisma/migrations");

const connectionString = process.env.DATABASE_URL;
if (!connectionString) throw new Error("DATABASE_URL is not set");
const pool = new Pool({ connectionString });

/** Row counts of every table outside the catalogue schema. */
async function otherTableCounts(): Promise<Record<string, number>> {
  const tables = await pool.query(
    `SELECT table_schema AS s, table_name AS n FROM information_schema.tables
     WHERE table_type = 'BASE TABLE'
       AND table_schema NOT IN ('pg_catalog', 'information_schema', 'catalogue')
     ORDER BY 1, 2`,
  );
  const counts: Record<string, number> = {};
  for (const { s, n } of tables.rows) {
    const result = await pool.query(`SELECT COUNT(*)::int AS c FROM "${s}"."${n}"`);
    counts[`${s}.${n}`] = result.rows[0].c;
  }
  return counts;
}

const before = await otherTableCounts();

await pool.query(`CREATE SCHEMA IF NOT EXISTS "catalogue"`);
await pool.query(
  `CREATE TABLE IF NOT EXISTS "catalogue"."applied_migrations" (
     name TEXT PRIMARY KEY,
     applied_at TIMESTAMPTZ NOT NULL DEFAULT now()
   )`,
);
const applied = new Set(
  (await pool.query(`SELECT name FROM "catalogue"."applied_migrations"`)).rows.map(
    (row) => row.name as string,
  ),
);

const names = (await readdir(migrationsDir, { withFileTypes: true }))
  .filter((entry) => entry.isDirectory())
  .map((entry) => entry.name)
  .sort();

for (const name of names) {
  if (applied.has(name)) {
    console.log(`skip     ${name} (already applied)`);
    continue;
  }
  const sql = await Bun.file(path.join(migrationsDir, name, "migration.sql")).text();
  if (/\bDROP\s+(TABLE|SCHEMA|COLUMN)\b|\bTRUNCATE\b/i.test(sql)) {
    throw new Error(
      `${name} contains a destructive statement. Review it and apply it by hand if it is intended.`,
    );
  }
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await client.query(sql);
    await client.query(
      `INSERT INTO "catalogue"."applied_migrations" (name) VALUES ($1)`,
      [name],
    );
    await client.query("COMMIT");
    console.log(`applied  ${name}`);
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally {
    client.release();
  }
}

const after = await otherTableCounts();
const changed = Object.keys({ ...before, ...after }).filter(
  (table) => before[table] !== after[table],
);
console.log(
  changed.length === 0
    ? `Tables outside "catalogue": ${Object.keys(after).length} tables, row counts unchanged.`
    : `WARNING: row counts changed outside "catalogue": ${changed.join(", ")}`,
);
await pool.end();
